# ! [doc = " This module contains the implementation for `slice::select_nth_unstable`."] # ! [doc = " It uses an introselect algorithm based on ipnsort by Lukas Bergdoll and Orson Peters,"] # ! [doc = " published at: <https://github.com/Voultapher/sort-research-rs/tree/main/ipnsort>"] # ! [doc = ""] # ! [doc = " The fallback algorithm used for introselect is Median of Medians using Tukey's Ninther"] # ! [doc = " for pivot selection. Using this as a fallback ensures O(n) worst case running time with"] # ! [doc = " better performance than one would get using heapsort as fallback."] use split_decls_genesis :: ourprelude :: * ; use crate :: cfg_select ; use crate :: mem :: { self , SizedTypeProperties } ; #[cfg (not (feature = "optimize_for_size"))] use crate :: slice :: sort :: shared :: pivot :: choose_pivot ; use crate :: slice :: sort :: shared :: smallsort :: insertion_sort_shift_left ; use crate :: slice :: sort :: unstable :: quicksort :: partition ; #[doc = " Reorders the slice such that the element at `index` is at its final sorted position."] pub (crate) fn partition_at_index < T , F > (v : & mut [T] , index : usize , mut is_less : F ,) -> (& mut [T] , & mut T , & mut [T]) where F : FnMut (& T , & T) -> bool , { let len = v . len () ; if index >= len { panic ! ("partition_at_index index {} greater than length of slice {}" , index , len) ; } if T :: IS_ZST { } else if index == len - 1 { let max_idx = max_index (v , & mut is_less) . unwrap () ; v . swap (max_idx , index) ; } else if index == 0 { let min_idx = min_index (v , & mut is_less) . unwrap () ; v . swap (min_idx , index) ; } else { cfg_select ! { feature = "optimize_for_size" => { median_of_medians (v , & mut is_less , index) ; } _ => { partition_at_index_loop (v , index , None , & mut is_less) ; } } } let (left , right) = v . split_at_mut (index) ; let (pivot , right) = right . split_at_mut (1) ; let pivot = & mut pivot [0] ; (left , pivot , right) } const INSERTION_SORT_THRESHOLD : usize = 16 ; #[cfg (not (feature = "optimize_for_size"))] fn partition_at_index_loop < 'a , T , F > (mut v : & 'a mut [T] , mut index : usize , mut ancestor_pivot : Option < & 'a T > , is_less : & mut F ,) where F : FnMut (& T , & T) -> bool , { let mut limit = 16 ; loop { if v . len () <= INSERTION_SORT_THRESHOLD { if v . len () >= 2 { insertion_sort_shift_left (v , 1 , is_less) ; } return ; } if limit == 0 { median_of_medians (v , is_less , index) ; return ; } limit -= 1 ; let pivot_pos = choose_pivot (v , is_less) ; if let Some (p) = ancestor_pivot { let pivot = & v [pivot_pos] ; if ! is_less (p , pivot) { let num_lt = partition (v , pivot_pos , & mut | a , b | ! is_less (b , a)) ; let mid = num_lt + 1 ; if mid > index { return ; } v = & mut v [mid ..] ; index = index - mid ; ancestor_pivot = None ; continue ; } } let mid = partition (v , pivot_pos , is_less) ; let (left , right) = v . split_at_mut (mid) ; let (pivot , right) = right . split_at_mut (1) ; let pivot = & pivot [0] ; if mid < index { v = right ; index = index - mid - 1 ; ancestor_pivot = Some (pivot) ; } else if mid > index { v = left ; } else { return ; } } } #[doc = " Helper function that returns the index of the minimum element in the slice using the given"] #[doc = " comparator function"] fn min_index < T , F : FnMut (& T , & T) -> bool > (slice : & [T] , is_less : & mut F) -> Option < usize > { slice . iter () . enumerate () . reduce (| acc , t | if is_less (t . 1 , acc . 1) { t } else { acc }) . map (| (i , _) | i) } #[doc = " Helper function that returns the index of the maximum element in the slice using the given"] #[doc = " comparator function"] fn max_index < T , F : FnMut (& T , & T) -> bool > (slice : & [T] , is_less : & mut F) -> Option < usize > { slice . iter () . enumerate () . reduce (| acc , t | if is_less (acc . 1 , t . 1) { t } else { acc }) . map (| (i , _) | i) } #[doc = " Selection algorithm to select the k-th element from the slice in guaranteed O(n) time."] #[doc = " This is essentially a quickselect that uses Tukey's Ninther for pivot selection"] fn median_of_medians < T , F : FnMut (& T , & T) -> bool > (mut v : & mut [T] , is_less : & mut F , mut k : usize) { debug_assert ! (k < v . len ()) ; debug_assert ! (! T :: IS_ZST) ; loop { if v . len () <= INSERTION_SORT_THRESHOLD { if v . len () >= 2 { insertion_sort_shift_left (v , 1 , is_less) ; } return ; } if k == v . len () - 1 { let max_idx = max_index (v , is_less) . unwrap () ; v . swap (max_idx , k) ; return ; } else if k == 0 { let min_idx = min_index (v , is_less) . unwrap () ; v . swap (min_idx , k) ; return ; } let p = median_of_ninthers (v , is_less) ; if p == k { return ; } else if p > k { v = & mut v [.. p] ; } else { v = & mut v [p + 1 ..] ; k -= p + 1 ; } } } fn median_of_ninthers < T , F : FnMut (& T , & T) -> bool > (v : & mut [T] , is_less : & mut F) -> usize { let frac = if v . len () <= 1024 { v . len () / 12 } else if v . len () <= 128_usize . saturating_mul (1024) { v . len () / 64 } else { v . len () / 1024 } ; let pivot = frac / 2 ; let lo = v . len () / 2 - pivot ; let hi = frac + lo ; let gap = (v . len () - 9 * frac) / 4 ; let mut a = lo - 4 * frac - gap ; let mut b = hi + gap ; for i in lo .. hi { ninther (v , is_less , a , i - frac , b , a + 1 , i , b + 1 , a + 2 , i + frac , b + 2) ; a += 3 ; b += 3 ; } median_of_medians (& mut v [lo .. lo + frac] , is_less , pivot) ; partition (v , lo + pivot , is_less) } #[doc = " Moves around the 9 elements at the indices a..i, such that"] #[doc = " `v[d]` contains the median of the 9 elements and the other"] #[doc = " elements are partitioned around it."] fn ninther < T , F : FnMut (& T , & T) -> bool > (v : & mut [T] , is_less : & mut F , a : usize , mut b : usize , c : usize , mut d : usize , e : usize , mut f : usize , g : usize , mut h : usize , i : usize ,) { b = median_idx (v , is_less , a , b , c) ; h = median_idx (v , is_less , g , h , i) ; if is_less (& v [h] , & v [b]) { mem :: swap (& mut b , & mut h) ; } if is_less (& v [f] , & v [d]) { mem :: swap (& mut d , & mut f) ; } if is_less (& v [e] , & v [d]) { } else if is_less (& v [f] , & v [e]) { d = f ; } else { if is_less (& v [e] , & v [b]) { v . swap (e , b) ; } else if is_less (& v [h] , & v [e]) { v . swap (e , h) ; } return ; } if is_less (& v [d] , & v [b]) { d = b ; } else if is_less (& v [h] , & v [d]) { d = h ; } v . swap (d , e) ; } #[doc = " returns the index pointing to the median of the 3"] #[doc = " elements `v[a]`, `v[b]` and `v[c]`"] fn median_idx < T , F : FnMut (& T , & T) -> bool > (v : & [T] , is_less : & mut F , mut a : usize , b : usize , mut c : usize ,) -> usize { if is_less (& v [c] , & v [a]) { mem :: swap (& mut a , & mut c) ; } if is_less (& v [c] , & v [b]) { return c ; } if is_less (& v [b] , & v [a]) { return a ; } b }